prompt.text:
Repair the complete source below. `pointInsideBeam(beam, point)` determines whether a 3D point lies within a finite cone. `beam` must contain three-element numeric arrays `origin` and `target`, a finite non-negative `range`, and a finite `halfAngle` from 0 through π; `point` must be a three-element numeric array. Invalid shapes or non-finite coordinates throw `TypeError`; invalid range or angle throws `RangeError`; identical origin and target throw `RangeError`. A point is inside when its distance from origin is at most range and its angular displacement from the origin-to-target direction is at most halfAngle. The origin itself is inside. Boundaries are inclusive. Do not mutate inputs. Return a corrected complete CommonJS source file exporting exactly `{ pointInsideBeam }`.

```javascript
'use strict';

function pointInsideBeam(beam, point) {
  const vector = (value, name) => {
    if (!Array.isArray(value) || value.length !== 3 || value.some((n) => typeof n !== 'number' || !Number.isFinite(n))) {
      throw new TypeError(`${name} must be a finite 3D vector`);
    }
  };
  if (beam === null || typeof beam !== 'object' || Array.isArray(beam)) throw new TypeError('beam must be an object');
  vector(beam.origin, 'origin');
  vector(beam.target, 'target');
  vector(point, 'point');
  if (typeof beam.range !== 'number' || !Number.isFinite(beam.range) || beam.range < 0) throw new RangeError('invalid range');
  if (typeof beam.halfAngle !== 'number' || !Number.isFinite(beam.halfAngle) || beam.halfAngle < 0 || beam.halfAngle > Math.PI) throw new RangeError('invalid halfAngle');

  const direction = beam.target.map((value, i) => value - beam.origin[i]);
  const offset = beam.origin.map((value, i) => value - point[i]);
  const directionLength = Math.hypot(...direction);
  const distance = Math.hypot(...offset);
  if (directionLength === 0) throw new RangeError('origin and target must differ');
  if (distance === 0) return true;
  if (distance > beam.range) return false;

  const cosine = direction.reduce((sum, value, i) => sum + value * offset[i], 0) / (directionLength * distance);
  return cosine >= Math.cos(beam.halfAngle);
}

module.exports = { pointInsideBeam };
```

