'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['pointInsideBeam']);
const { pointInsideBeam } = api;
assert.strictEqual(typeof pointInsideBeam, 'function');

const origin = Object.freeze([0, 0, 0]);
const target = Object.freeze([1, 0, 0]);
const beam = Object.freeze({ origin, target, range: 5, halfAngle: Math.PI / 4 });
assert.strictEqual(pointInsideBeam(beam, Object.freeze([1, 0, 0])), true);
assert.strictEqual(pointInsideBeam(beam, Object.freeze([3, 1, 0])), true);
assert.strictEqual(pointInsideBeam(beam, Object.freeze([-1, 0, 0])), false);
assert.strictEqual(pointInsideBeam(beam, Object.freeze([5, 0, 0])), true);
assert.strictEqual(pointInsideBeam(beam, Object.freeze([5.0000001, 0, 0])), false);
assert.strictEqual(pointInsideBeam(beam, Object.freeze([0, 0, 0])), true);
assert.deepStrictEqual(origin, [0, 0, 0]);
assert.deepStrictEqual(target, [1, 0, 0]);

assert.strictEqual(pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: 2, halfAngle: 0 }, [2, 0, 0]), true);
assert.strictEqual(pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: 2, halfAngle: 0 }, [1, 0.0001, 0]), false);
assert.strictEqual(pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: 2, halfAngle: Math.PI / 2 }, [0, 2, 0]), true);
assert.strictEqual(pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: 2, halfAngle: Math.PI }, [-2, 0, 0]), true);
assert.strictEqual(pointInsideBeam({ origin: [2, 3, 4], target: [3, 3, 4], range: 0, halfAngle: 0 }, [2, 3, 4]), true);

for (const badBeam of [null, [], 'x', 1, {}, { origin: [0, 0], target: [1, 0, 0], range: 1, halfAngle: 0 }, { origin: [0, 0, 0], target: [1, NaN, 0], range: 1, halfAngle: 0 }]) {
  assert.throws(() => pointInsideBeam(badBeam, [0, 0, 0]), TypeError);
}
for (const badPoint of [null, {}, [0, 0], [0, 0, Infinity], ['0', 0, 0]]) {
  assert.throws(() => pointInsideBeam(beam, badPoint), TypeError);
}
for (const badRange of [-1, Infinity, NaN, '5']) {
  assert.throws(() => pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: badRange, halfAngle: 0 }, [0, 0, 0]), RangeError);
}
for (const badAngle of [-0.01, Math.PI + 0.01, Infinity, NaN, '0']) {
  assert.throws(() => pointInsideBeam({ origin: [0, 0, 0], target: [1, 0, 0], range: 1, halfAngle: badAngle }, [0, 0, 0]), RangeError);
}
assert.throws(() => pointInsideBeam({ origin: [1, 2, 3], target: [1, 2, 3], range: 1, halfAngle: 0 }, [1, 2, 3]), RangeError);

